import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import stringToColor from 'flarum/common/utils/stringToColor';
export const LIST_MAX = 30;
export const NEAR_MAX = 10;
export const SOURCE = 'member-map';
export function profileUrl(slug) {
  return app.route('user', {
    username: slug
  });
}

/** An avatar as DOM, text set as text. */
export function avatarEl(name, url, size = '') {
  if (url) {
    const img = document.createElement('img');
    img.className = 'Avatar ' + size;
    img.src = url;
    img.alt = '';
    img.loading = 'lazy';
    img.decoding = 'async';
    return img;
  }
  const span = document.createElement('span');
  span.className = 'Avatar ' + size;
  span.style.setProperty('--avatar-bg', '#' + stringToColor(name));
  span.textContent = (name || '?').charAt(0).toUpperCase();
  return span;
}

/** The same avatar inside Mithril views (cards, lists): drawn once as DOM. */
export class Avatar extends Component {
  view() {
    return m("span", {
      className: "MemberMap-avatar",
      oncreate: vnode => vnode.dom.replaceChildren(avatarEl(this.attrs.name, this.attrs.url, this.attrs.size || ''))
    });
  }
}
export function icon(name) {
  const i = document.createElement('i');
  i.className = name;
  i.setAttribute('aria-hidden', 'true');
  return i;
}

/** "Sat, Dec 6, 7:00 PM CST": a meetup's time in its own place's zone. */
export function meetupWhen(row) {
  try {
    return new Intl.DateTimeFormat(app.translator.getLocale() || undefined, {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      timeZone: row[5] || undefined,
      timeZoneName: 'short'
    }).format(new Date(row[4]));
  } catch {
    // An unknown zone name in an old browser: the viewer's own time instead.
    return new Date(row[4]).toLocaleString();
  }
}
flarum.reg.add('ernestdefoe-member-map', 'forum/components/mapPage/shared', { LIST_MAX: LIST_MAX,NEAR_MAX: NEAR_MAX,SOURCE: SOURCE,profileUrl: profileUrl,avatarEl: avatarEl,Avatar: Avatar,icon: icon,meetupWhen: meetupWhen, });